{"version":3,"file":"lolfi.js","sourceRoot":"/","sources":["../test/utils/lolfi.ts"],"names":[],"mappings":";;;;;AAaA,sCA6CC;AA1DD,6CAAwC;AAExC,2CAA4C;AAC5C,iCAA6D;AAE7D,sEAA4C;AAG5C,6DAAoE;AAGpE,2DAA6D;AAEtD,KAAK,UAAU,aAAa,CAAC,OAInC;IACC,MAAM,SAAS,GAAG,OAAO,CAAC,OAAO,CAAC,EAAE,IAAI,IAAA,uBAAS,EAAC,GAAG,EAAE,GAAG,CAAC,CAAC;IAC5D,MAAM,WAAW,GAAG,GAAG,OAAO,CAAC,OAAO,CAAC,IAAI,IAAI,uBAAuB,EAAE,CAAC;IAEzE,MAAM,OAAO,GAAG,MAAM,IAAA,4BAAoB,EAAC;QACzC,QAAQ,EAAE,CAAC,EAAE,GAAG,OAAO,CAAC,OAAO,EAAE,IAAI,EAAE,WAAW,EAAE,EAAE,EAAE,SAAS,EAAE,CAAC;KACrE,CAAC,CAAC;IAEH,MAAM,iBAAiB,GAAG,MAAM,OAAO,CAAC,IAAI;SACzC,IAAI,CAAC,sBAAsB,CAAC;SAC5B,GAAG,CAAC,EAAE,MAAM,EAAE,OAAO,CAAC,MAAM,EAAE,CAAC;SAC/B,MAAM,CAAC,MAAM,EAAE,OAAO,EAAE;QACvB,QAAQ,EAAE,YAAY,GAAG,IAAI,IAAI,EAAE,CAAC,WAAW,EAAE,GAAG,MAAM;QAC1D,WAAW,EAAE,uBAAe,CAAC,GAAG;KACjC,CAAC;SACD,MAAM,CAAC,mBAAU,CAAC,EAAE,CAAC,CAAC;IAEzB,MAAM,EAAE,EAAE,EAAE,KAAK,EAAE,GAAG,iBAAiB,CAAC,IAA+B,CAAC;IACxE,MAAM,IAAA,yBAAa,EAAC,KAAK,IAAI,EAAE;QAC7B,MAAM,WAAW,GAAG,MAAM,OAAO,CAAC,IAAI;aACnC,GAAG,CAAC,gBAAgB,KAAK,EAAE,CAAC;aAC5B,GAAG,CAAC,EAAE,MAAM,EAAE,OAAO,CAAC,MAAM,EAAE,CAAC;aAC/B,MAAM,CAAC,mBAAU,CAAC,EAAE,CAAC,CAAC;QAEzB,MAAM,MAAM,GAAyB,WAAW,CAAC,IAAuB,CAAC,MAAM,CAAC;QAChF,IAAI,MAAM,KAAK,QAAQ,EAAE,CAAC;YACxB,OAAO,CAAC,KAAK,CAAE,WAAW,CAAC,IAAuB,CAAC,MAAM,CAAC,CAAC;YAC3D,OAAO,CAAC,KAAK,CAAE,WAAW,CAAC,IAAuB,CAAC,KAAK,CAAC,GAAG,CAAC,CAAC,IAAI,EAAE,EAAE,CAAC,IAAI,CAAC,MAAM,CAAC,CAAC,CAAC;YACrF,MAAM,CAAC,MAAM,CAAC,CAAC,IAAI,CAAC,QAAQ,CAAC,CAAC;QAChC,CAAC;QAED,MAAM,CAAC,MAAM,CAAC,CAAC,IAAI,CAAC,WAAyC,CAAC,CAAC;IACjE,CAAC,EAAgB,KAAK,CAAC,CAAC;IAExB,MAAM,eAAe,GAAG,MAAM,OAAO,CAAC,IAAI;SACvC,GAAG,CAAC,mCAAmC,CAAC;SACxC,KAAK,CAAC,EAAE,MAAM,EAAE,GAAG,WAAW,KAAK,SAAS,GAAG,EAAE,CAAC;SAClD,GAAG,CAAC,EAAE,MAAM,EAAE,OAAO,CAAC,MAAM,EAAE,CAAC;SAC/B,MAAM,CAAC,mBAAU,CAAC,EAAE,CAAC,CAAC;IAEzB,OAAO,EAAE,EAAE,EAAE,IAAA,4BAAe,EAAC,eAAe,CAAC,IAAI,CAAC,KAAK,CAAC,CAAC,CAAC,EAAE,oBAAoB,WAAW,GAAG,CAAC,CAAC,EAAE,EAAE,CAAC;AACvG,CAAC","sourcesContent":["import { randomInt } from 'node:crypto';\n\nimport { HttpStatus } from '@nestjs/common';\nimport { generateLolfiArchive, type LolfiData } from 'lolfi';\nimport supertest from 'supertest';\nimport waitForExpect from 'wait-for-expect';\n\nimport { PrismaJobStatusEnum } from '../../src/generated/prisma/enums';\nimport { FILE_MIME_TYPES } from '../../src/modules/framework/files';\nimport { IngestedLolfiArchiveDto } from '../../src/modules/ingest/infrastructure/ingest.dto';\nimport { DetailedJobDto } from '../../src/modules/ingest/jobs/queries/details-job.query';\nimport { assertIsDefined } from '../../src/utils/is-defined';\n\nexport async function createSession(options: {\n  cookie: string;\n  session: LolfiData['sessions'][number];\n  http: ReturnType<typeof supertest.agent>;\n}): Promise<{ id: string }> {\n  const sessionId = options.session.id || randomInt(100, 1e6);\n  const sessionName = `${options.session.name || 'Transparence annuelle'}`;\n\n  const archive = await generateLolfiArchive({\n    sessions: [{ ...options.session, name: sessionName, id: sessionId }],\n  });\n\n  const ingestionResponse = await options.http\n    .post('/api/ingest/v1/lolfi')\n    .set({ cookie: options.cookie })\n    .attach('file', archive, {\n      filename: 'LOLFI_CSM_' + new Date().toISOString() + `.zip`,\n      contentType: FILE_MIME_TYPES.zip,\n    })\n    .expect(HttpStatus.OK);\n\n  const { id: jobId } = ingestionResponse.body as IngestedLolfiArchiveDto;\n  await waitForExpect(async () => {\n    const jobResponse = await options.http\n      .get(`/api/jobs/v1/${jobId}`)\n      .set({ cookie: options.cookie })\n      .expect(HttpStatus.OK);\n\n    const status: PrismaJobStatusEnum = (jobResponse.body as DetailedJobDto).status;\n    if (status === 'FAILED') {\n      console.error((jobResponse.body as DetailedJobDto).errors);\n      console.error((jobResponse.body as DetailedJobDto).files.map((file) => file.errors));\n      expect(status).toBe('FAILED');\n    }\n\n    expect(status).toBe('SUCCEEDED' satisfies PrismaJobStatusEnum);\n  }, /* timeout */ 2_000);\n\n  const sessionResponse = await options.http\n    .get('/api/sessions/v2/garde-des-sceaux')\n    .query({ search: `${sessionName} (${sessionId})` })\n    .set({ cookie: options.cookie })\n    .expect(HttpStatus.OK);\n\n  return { id: assertIsDefined(sessionResponse.body.items[0], `unknown session \"${sessionName}\"`).id };\n}\n"]}
